+function sourceHasTokenTotals(source) {
+  return source?.tokens_total !== null && source?.tokens_total !== undefined;
+}
+
+function sourceStatusText(source, active) {
+  if (active) return 'Focused';
+  if (source?.status !== 'active') return 'Planned adapter';
+  if (sourceHasTokenTotals(source)) return 'Included in totals';
+  if (source?.sessions === null || source?.sessions === undefined) return `No ${fmtPeriod()} token records`;
+  return 'Session provenance only';
+}
+
+function sourceActionText(source, active) {
+  if (active) return `Showing chart + table for ${source?.label || 'source'}`;
+  if (source?.status !== 'active') return 'Not connected';
+  if (sourceHasTokenTotals(source)) return 'Click to focus chart';
+  if (source?.sessions === null || source?.sessions === undefined) return 'Source detected · no chart data';
+  return 'History only · tokens unavailable';
+}
